13	void FunctionNameNormalizer::visit(IAST * ast)
14	{
15	    if (!ast)
16	        return;
17	
18	    // Normalize only selected children. Avoid normalizing engine clause because some engine might
19	    // have the same name as function, e.g. Log.
20	    if (auto * node_storage = ast->as<ASTStorage>())
21	    {
22	        visit(node_storage->partition_by);
23	        visit(node_storage->primary_key);
24	        visit(node_storage->order_by);
25	        visit(node_storage->sample_by);
26	        visit(node_storage->ttl_table);
27	        return;
28	    }
29	
30	    // Normalize only selected children. Avoid normalizing type clause because some type might
31	    // have the same name as function, e.g. Date.
32	    if (auto * node_decl = ast->as<ASTColumnDeclaration>())
33	    {
34	        visit(node_decl->default_expression.get());
35	        visit(node_decl->ttl.get());
36	        return;
37	    }
38	
39	    if (auto * node_func = ast->as<ASTFunction>())
40	        node_func->name = getAggregateFunctionCanonicalNameIfAny(getFunctionCanonicalNameIfAny(node_func->name));
41	
42	    for (auto & child : ast->children)
43	        visit(child.get());
44	}
