70	/** Higher-order functions for arrays.
71	  * These functions optionally apply a map (transform) to array (or multiple arrays of identical size) by lambda function,
72	  *  and return some result based on that transformation.
73	  *
74	  * Examples:
75	  * arrayMap(x1,...,xn -> expression, array1,...,arrayn) - apply the expression to each element of the array (or set of parallel arrays).
76	  * arrayFilter(x -> predicate, array) - leave in the array only the elements for which the expression is true.
77	  *
78	  * For some functions arrayCount, arrayExists, arrayAll, an overload of the form f(array) is available,
79	  *  which works in the same way as f(x -> x, array).
80	  *
81	  * See the example of Impl template parameter in arrayMap.cpp
82	  */
83	template <typename Impl, typename Name>
84	class FunctionArrayMapped : public IFunction
85	{
86	public:
87	    static constexpr auto name = Name::name;
88	    static FunctionPtr create(ContextPtr) { return std::make_shared<FunctionArrayMapped>(); }
89	
90	    String getName() const override
91	    {
92	        return name;
93	    }
94	
95	    bool isVariadic() const override { return true; }
96	    size_t getNumberOfArguments() const override { return 0; }
97	    bool isSuitableForShortCircuitArgumentsExecution(const DataTypesWithConstInfo & /*arguments*/) const override { return true; }
