99	    /// Called if at least one function argument is a lambda expression.
100	    /// For argument-lambda expressions, it defines the types of arguments of these expressions.
101	    void getLambdaArgumentTypes(DataTypes & arguments) const override
102	    {
103	        if (arguments.empty())
104	            throw Exception(ErrorCodes::NUMBER_OF_ARGUMENTS_DOESNT_MATCH,
105	                            "Function {} needs at least one argument, passed {}", getName(), arguments.size());
106	
107	        if (arguments.size() == 1)
108	            throw Exception(ErrorCodes::NUMBER_OF_ARGUMENTS_DOESNT_MATCH,
109	                            "Function {} needs at least one argument with data", getName());
110	
111	        if (arguments.size() > 2 && Impl::needOneArray())
112	            throw Exception(ErrorCodes::NUMBER_OF_ARGUMENTS_DOESNT_MATCH,
113	                            "Function {} needs one argument with data", getName());
114	
115	        size_t nested_types_count = std::is_same_v<typename Impl::data_type, DataTypeMap> ? (arguments.size() - 1) * 2 : (arguments.size() - 1);
116	        DataTypes nested_types(nested_types_count);
117	        for (size_t i = 0; i < arguments.size() - 1; ++i)
118	        {
119	            const auto * array_type = checkAndGetDataType<typename Impl::data_type>(&*arguments[i + 1]);
120	            if (!array_type)
121	                throw Exception("Argument " + toString(i + 2) + " of function " + getName() + " must be array. Found "
122	                                + arguments[i + 1]->getName() + " instead.", ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT);
123	            if constexpr (std::is_same_v<typename Impl::data_type, DataTypeMap>)
124	            {
125	                nested_types[2 * i] = recursiveRemoveLowCardinality(array_type->getKeyType());
126	                nested_types[2 * i + 1] = recursiveRemoveLowCardinality(array_type->getValueType());
127	            }
128	            else if constexpr (std::is_same_v<typename Impl::data_type, DataTypeArray>)
129	            {
130	                nested_types[i] = recursiveRemoveLowCardinality(array_type->getNestedType());
131	            }
132	        }
133	
134	        const DataTypeFunction * function_type = checkAndGetDataType<DataTypeFunction>(arguments[0].get());
135	        if (!function_type || function_type->getArgumentTypes().size() != nested_types.size())
136	            throw Exception(
137	                ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT,
138	                "First argument for this overload of {} must be a function with {} arguments, found {} instead",
139	                getName(), nested_types.size(), arguments[0]->getName());
140	
141	        arguments[0] = std::make_shared<DataTypeFunction>(nested_types);
142	    }
