221	    ColumnPtr executeImpl(const ColumnsWithTypeAndName & arguments, const DataTypePtr &, size_t /*input_rows_count*/) const override
222	    {
223	        if (arguments.size() == 1)
224	        {
225	            ColumnPtr column_array_ptr = arguments[0].column;
226	            const auto * column_array = checkAndGetColumn<typename Impl::column_type>(column_array_ptr.get());
227	
228	            if (!column_array)
229	            {
230	                const ColumnConst * column_const_array = checkAndGetColumnConst<typename Impl::column_type>(column_array_ptr.get());
231	                if (!column_const_array)
232	                    throw Exception("Expected array column, found " + column_array_ptr->getName(), ErrorCodes::ILLEGAL_COLUMN);
233	                column_array_ptr = column_const_array->convertToFullColumn();
234	                column_array = assert_cast<const typename Impl::column_type *>(column_array_ptr.get());
235	            }
236	
237	            if constexpr (std::is_same_v<typename Impl::column_type, ColumnMap>)
238	            {
239	                return Impl::execute(*column_array, column_array->getNestedColumn().getDataPtr());
240	            }
241	            else
242	            {
243	                return Impl::execute(*column_array, column_array->getDataPtr());
244	            }
245	        }
246	        else
247	        {
248	            const auto & column_with_type_and_name = arguments[0];
249	
250	            if (!column_with_type_and_name.column)
251	                throw Exception("First argument for function " + getName() + " must be a function.",
252	                    ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT);
253	
254	            const auto * column_function = typeid_cast<const ColumnFunction *>(column_with_type_and_name.column.get());
255	
256	            if (!column_function)
257	                throw Exception("First argument for function " + getName() + " must be a function.",
258	                    ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT);
259	
260	            ColumnPtr offsets_column;
261	
262	            ColumnPtr column_first_array_ptr;
263	            const typename Impl::column_type * column_first_array = nullptr;
264	
265	            ColumnsWithTypeAndName arrays;
266	            arrays.reserve(arguments.size() - 1);
267	
268	            for (size_t i = 1; i < arguments.size(); ++i)
269	            {
270	                const auto & array_with_type_and_name = arguments[i];
271	
272	                ColumnPtr column_array_ptr = array_with_type_and_name.column;
273	                const auto * column_array = checkAndGetColumn<typename Impl::column_type>(column_array_ptr.get());
274	
275	                const DataTypePtr & array_type_ptr = array_with_type_and_name.type;
276	                const auto * array_type = checkAndGetDataType<typename Impl::data_type>(array_type_ptr.get());
277	
278	                if (!column_array)
279	                {
280	                    const ColumnConst * column_const_array = checkAndGetColumnConst<typename Impl::column_type>(column_array_ptr.get());
281	                    if (!column_const_array)
282	                        throw Exception("Expected array column, found " + column_array_ptr->getName(), ErrorCodes::ILLEGAL_COLUMN);
283	                    column_array_ptr = recursiveRemoveLowCardinality(column_const_array->convertToFullColumn());
284	                    column_array = checkAndGetColumn<typename Impl::column_type>(column_array_ptr.get());
285	                }
286	
287	                if (!array_type)
288	                    throw Exception("Expected array type, found " + array_type_ptr->getName(), ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT);
289	
290	                if (!offsets_column)
291	                {
292	                    offsets_column = getOffsetsPtr(*column_array);
293	                }
294	                else
295	                {
296	                    /// The first condition is optimization: do not compare data if the pointers are equal.
297	                    if (getOffsetsPtr(*column_array) != offsets_column
298	                        && getOffsets(*column_array) != typeid_cast<const ColumnArray::ColumnOffsets &>(*offsets_column).getData())
299	                        throw Exception("Arrays passed to " + getName() + " must have equal size", ErrorCodes::SIZES_OF_ARRAYS_DOESNT_MATCH);
300	                }
301	
302	                if (i == 1)
303	                {
304	                    column_first_array_ptr = column_array_ptr;
305	                    column_first_array = column_array;
306	                }
307	
308	                if constexpr (std::is_same_v<DataTypeMap, typename Impl::data_type>)
309	                {
310	                    arrays.emplace_back(ColumnWithTypeAndName(
311	                        column_array->getNestedData().getColumnPtr(0), recursiveRemoveLowCardinality(array_type->getKeyType()), array_with_type_and_name.name+".key"));
312	                    arrays.emplace_back(ColumnWithTypeAndName(
313	                        column_array->getNestedData().getColumnPtr(1), recursiveRemoveLowCardinality(array_type->getValueType()), array_with_type_and_name.name+".value"));
314	                }
315	                else
316	                {
317	                    arrays.emplace_back(ColumnWithTypeAndName(column_array->getDataPtr(),
318	                                                            recursiveRemoveLowCardinality(array_type->getNestedType()),
319	                                                            array_with_type_and_name.name));
320	                }
321	            }
322	
323	            /// Put all the necessary columns multiplied by the sizes of arrays into the columns.
324	            auto replicated_column_function_ptr = IColumn::mutate(column_function->replicate(getOffsets(*column_first_array)));
325	            auto * replicated_column_function = typeid_cast<ColumnFunction *>(replicated_column_function_ptr.get());
326	            replicated_column_function->appendArguments(arrays);
327	
328	            auto lambda_result = replicated_column_function->reduce();
329	            if (lambda_result.column->lowCardinality())
330	                lambda_result.column = lambda_result.column->convertToFullColumnIfLowCardinality();
331	
332	            if (Impl::needBoolean())
333	            {
334	                /// If result column is Nothing or Nullable(Nothing), just create const UInt8 column with 0 value.
335	                if (isNothing(removeNullable(lambda_result.type)))
336	                {
337	                    auto result_type = std::make_shared<DataTypeUInt8>();
338	                    lambda_result.column = result_type->createColumnConst(lambda_result.column->size(), 0);
339	                }
340	                /// If result column is Nullable(UInt8), then extract nested column and write 0 in all rows
341	                /// when we have NULL.
342	                else if (lambda_result.column->isNullable())
343	                {
344	                    auto result_column = IColumn::mutate(std::move(lambda_result.column));
345	
346	                    if (isColumnConst(*result_column))
347	                    {
348	                        UInt8 value = result_column->empty() ? 0 : result_column->getBool(0);
349	                        auto result_type = std::make_shared<DataTypeUInt8>();
350	                        lambda_result.column = result_type->createColumnConst(result_column->size(), value);
351	                    }
352	                    else
353	                    {
354	                        auto * column_nullable = assert_cast<ColumnNullable *>(result_column.get());
355	                        auto & null_map = column_nullable->getNullMapData();
356	                        auto nested_column = IColumn::mutate(std::move(column_nullable->getNestedColumnPtr()));
357	                        auto & nested_data = assert_cast<ColumnUInt8 *>(nested_column.get())->getData();
358	                        for (size_t i = 0; i != nested_data.size(); ++i)
359	                        {
360	                            if (null_map[i])
361	                                nested_data[i] = 0;
362	                        }
363	                        lambda_result.column = std::move(nested_column);
364	                    }
365	                }
366	            }
367	
368	            return Impl::execute(*column_first_array, lambda_result.column);
369	        }
370	    }
