61	/// Convert from readline to replxx format.
62	///
63	/// replxx requires each history line to prepended with time line:
64	///
65	///     ### YYYY-MM-DD HH:MM:SS.SSS
66	///     select 1
67	///
68	/// And w/o those service lines it will load all lines from history file as
69	/// one history line for suggestion. And if there are lots of lines in file it
70	/// will take lots of time (getline() + tons of reallocations).
71	///
72	/// NOTE: this code uses std::ifstream/std::ofstream like original replxx code.
73	void convertHistoryFile(const std::string & path, replxx::Replxx & rx)
74	{
75	    std::ifstream in(path);
76	    if (!in)
77	    {
78	        rx.print("Cannot open %s reading (for conversion): %s\n",
79	            path.c_str(), errnoToString(errno).c_str());
80	        return;
81	    }
82	
83	    std::string line;
84	    if (getline(in, line).bad())
85	    {
86	        rx.print("Cannot read from %s (for conversion): %s\n",
87	            path.c_str(), errnoToString(errno).c_str());
88	        return;
89	    }
90	
91	    /// This is the marker of the date, no need to convert.
92	    static char const REPLXX_TIMESTAMP_PATTERN[] = "### dddd-dd-dd dd:dd:dd.ddd";
93	    if (line.empty() || (line.starts_with("### ") && line.size() == strlen(REPLXX_TIMESTAMP_PATTERN)))
94	    {
95	        return;
96	    }
97	
