139	    bool multiline_,
140	    Patterns extenders_,
141	    Patterns delimiters_,
142	    replxx::Replxx::highlighter_callback_t highlighter_)
143	    : LineReader(history_file_path_, multiline_, std::move(extenders_), std::move(delimiters_)), highlighter(std::move(highlighter_))
144	    , editor(getEditor())
145	{
146	    using namespace std::placeholders;
147	    using Replxx = replxx::Replxx;
148	
149	    if (!history_file_path.empty())
150	    {
151	        history_file_fd = open(history_file_path.c_str(), O_RDWR);
152	        if (history_file_fd < 0)
153	        {
154	            rx.print("Open of history file failed: %s\n", errnoToString(errno).c_str());
155	        }
156	        else
157	        {
158	            convertHistoryFile(history_file_path, rx);
159	
160	            if (flock(history_file_fd, LOCK_SH))
161	            {
162	                rx.print("Shared lock of history file failed: %s\n", errnoToString(errno).c_str());
163	            }
164	            else
165	            {
166	                if (!rx.history_load(history_file_path))
167	                {
168	                    rx.print("Loading history failed: %s\n", errnoToString(errno).c_str());
169	                }
170	
171	                if (flock(history_file_fd, LOCK_UN))
172	                {
173	                    rx.print("Unlock of history file failed: %s\n", errnoToString(errno).c_str());
174	                }
175	            }
176	        }
177	    }
178	
179	    rx.install_window_change_handler();
180	
181	    auto callback = [&suggest] (const String & context, size_t context_size)
182	    {
183	        return suggest.getCompletions(context, context_size);
184	    };
185	
186	    rx.set_completion_callback(callback);
187	    rx.set_complete_on_empty(false);
188	    rx.set_word_break_characters(word_break_characters);
189	    rx.set_ignore_case(true);
190	
191	    if (highlighter)
192	        rx.set_highlighter_callback(highlighter);
193	
194	    /// By default C-p/C-n binded to COMPLETE_NEXT/COMPLETE_PREV,
195	    /// bind C-p/C-n to history-previous/history-next like readline.
196	    rx.bind_key(Replxx::KEY::control('N'), [this](char32_t code) { return rx.invoke(Replxx::ACTION::HISTORY_NEXT, code); });
197	    rx.bind_key(Replxx::KEY::control('P'), [this](char32_t code) { return rx.invoke(Replxx::ACTION::HISTORY_PREVIOUS, code); });
198	
199	    auto commit_action = [this](char32_t code)
200	    {
201	        /// If we allow multiline and there is already something in the input, start a newline.
202	        /// NOTE: Lexer is only available if we use highlighter.
203	        if (highlighter && multiline && !replxx_last_is_delimiter)
204	            return rx.invoke(Replxx::ACTION::NEW_LINE, code);
205	        replxx_last_is_delimiter = false;
206	        return rx.invoke(Replxx::ACTION::COMMIT_LINE, code);
207	    };
208	    /// bind C-j to ENTER action.
209	    rx.bind_key(Replxx::KEY::control('J'), commit_action);
210	    rx.bind_key(Replxx::KEY::ENTER, commit_action);
211	
212	    /// By default COMPLETE_NEXT/COMPLETE_PREV was binded to C-p/C-n, re-bind
213	    /// to M-P/M-N (that was used for HISTORY_COMMON_PREFIX_SEARCH before, but
214	    /// it also binded to M-p/M-n).
215	    rx.bind_key(Replxx::KEY::meta('N'), [this](char32_t code) { return rx.invoke(Replxx::ACTION::COMPLETE_NEXT, code); });
216	    rx.bind_key(Replxx::KEY::meta('P'), [this](char32_t code) { return rx.invoke(Replxx::ACTION::COMPLETE_PREVIOUS, code); });
217	    /// By default M-BACKSPACE is KILL_TO_WHITESPACE_ON_LEFT, while in readline it is backward-kill-word
218	    rx.bind_key(Replxx::KEY::meta(Replxx::KEY::BACKSPACE), [this](char32_t code) { return rx.invoke(Replxx::ACTION::KILL_TO_BEGINING_OF_WORD, code); });
219	    /// By default C-w is KILL_TO_BEGINING_OF_WORD, while in readline it is unix-word-rubout
220	    rx.bind_key(Replxx::KEY::control('W'), [this](char32_t code) { return rx.invoke(Replxx::ACTION::KILL_TO_WHITESPACE_ON_LEFT, code); });
221	
222	    rx.bind_key(Replxx::KEY::meta('E'), [this](char32_t) { openEditor(); return Replxx::ACTION_RESULT::CONTINUE; });
223	}
