267	/// See comments in ShellCommand::executeImpl()
268	/// (for the vfork via dlsym())
269	int ReplxxLineReader::executeEditor(const std::string & path)
270	{
271	    std::vector<char> argv0(editor.data(), editor.data() + editor.size() + 1);
272	    std::vector<char> argv1(path.data(), path.data() + path.size() + 1);
273	    char * const argv[] = {argv0.data(), argv1.data(), nullptr};
274	
275	    static void * real_vfork = dlsym(RTLD_DEFAULT, "vfork");
276	    if (!real_vfork)
277	    {
278	        rx.print("Cannot find symbol vfork in myself: %s\n", errnoToString(errno).c_str());
279	        return -1;
280	    }
281	
282	    pid_t pid = reinterpret_cast<pid_t (*)()>(real_vfork)();
283	
284	    if (-1 == pid)
285	    {
286	        rx.print("Cannot vfork: %s\n", errnoToString(errno).c_str());
287	        return -1;
288	    }
289	
290	    /// Child
291	    if (0 == pid)
292	    {
293	        sigset_t mask;
294	        sigemptyset(&mask);
295	        sigprocmask(0, nullptr, &mask);
296	        sigprocmask(SIG_UNBLOCK, &mask, nullptr);
297	
298	        execvp(editor.c_str(), argv);
299	        rx.print("Cannot execute %s: %s\n", editor.c_str(), errnoToString(errno).c_str());
300	        _exit(-1);
301	    }
302	
303	    int status = 0;
304	    do
305	    {
306	        int exited_pid = waitpid(pid, &status, 0);
307	        if (exited_pid == -1)
308	        {
309	            if (errno == EINTR)
310	                continue;
311	
312	            rx.print("Cannot waitpid: %s\n", errnoToString(errno).c_str());
313	            return -1;
314	        }
315	        else
316	            break;
317	    } while (true);
318	    return status;
319	}
