321	void ReplxxLineReader::openEditor()
322	{
323	    char filename[] = "clickhouse_replxx_XXXXXX.sql";
324	    int fd = ::mkstemps(filename, 4);
325	    if (-1 == fd)
326	    {
327	        rx.print("Cannot create temporary file to edit query: %s\n", errnoToString(errno).c_str());
328	        return;
329	    }
330	
331	    replxx::Replxx::State state(rx.get_state());
332	
333	    size_t bytes_written = 0;
334	    const char * begin = state.text();
335	    size_t offset = strlen(state.text());
336	    while (bytes_written != offset)
337	    {
338	        ssize_t res = ::write(fd, begin + bytes_written, offset - bytes_written);
339	        if ((-1 == res || 0 == res) && errno != EINTR)
340	        {
341	            rx.print("Cannot write to temporary query file %s: %s\n", filename, errnoToString(errno).c_str());
342	            break;
343	        }
344	        bytes_written += res;
345	    }
346	
347	    if (0 != ::close(fd))
348	    {
349	        rx.print("Cannot close temporary query file %s: %s\n", filename, errnoToString(errno).c_str());
350	        return;
351	    }
352	
353	    if (0 == executeEditor(filename))
354	    {
355	        try
356	        {
357	            std::ifstream t(filename);
358	            std::string str;
359	            t.seekg(0, std::ios::end);
360	            str.reserve(t.tellg());
361	            t.seekg(0, std::ios::beg);
362	            str.assign((std::istreambuf_iterator<char>(t)), std::istreambuf_iterator<char>());
363	            rx.set_state(replxx::Replxx::State(str.c_str(), str.size()));
364	        }
365	        catch (...)
366	        {
367	            rx.print("Cannot read from temporary query file %s: %s\n", filename, errnoToString(errno).c_str());
368	            return;
369	        }
370	    }
371	
372	    if (bracketed_paste_enabled)
373	        enableBracketedPaste();
374	
375	    if (0 != ::unlink(filename))
376	        rx.print("Cannot remove temporary query file %s: %s\n", filename, errnoToString(errno).c_str());
377	}
