29	void FunctionFactory::registerFunction(
30	    const std::string & name,
31	    Value creator,
32	    CaseSensitiveness case_sensitiveness)
33	{
34	    if (!functions.emplace(name, creator).second)
35	        throw Exception("FunctionFactory: the function name '" + name + "' is not unique",
36	                        ErrorCodes::LOGICAL_ERROR);
37	
38	    String function_name_lowercase = Poco::toLower(name);
39	    if (isAlias(name) || isAlias(function_name_lowercase))
40	        throw Exception("FunctionFactory: the function name '" + name + "' is already registered as alias",
41	                        ErrorCodes::LOGICAL_ERROR);
42	
43	    if (case_sensitiveness == CaseInsensitive)
44	    {
45	        if (!case_insensitive_functions.emplace(function_name_lowercase, creator).second)
46	            throw Exception("FunctionFactory: the case insensitive function name '" + name + "' is not unique",
47	                ErrorCodes::LOGICAL_ERROR);
48	        case_insensitive_name_mapping[function_name_lowercase] = name;
49	    }
50	}
