54	    const std::string & name,
55	    ContextPtr context) const
56	{
57	    auto res = tryGetImpl(name, context);
58	    if (!res)
59	    {
60	        String extra_info;
61	        if (AggregateFunctionFactory::instance().hasNameOrAlias(name))
62	            extra_info = ". There is an aggregate function with the same name, but ordinary function is expected here";
63	
64	        auto hints = this->getHints(name);
65	        if (!hints.empty())
66	            throw Exception(ErrorCodes::UNKNOWN_FUNCTION, "Unknown function {}{}. Maybe you meant: {}", name, extra_info, toString(hints));
67	        else
68	            throw Exception(ErrorCodes::UNKNOWN_FUNCTION, "Unknown function {}{}", name, extra_info);
69	    }
70	
71	    return res;
