99	FunctionOverloadResolverPtr FunctionFactory::tryGetImpl(
100	    const std::string & name_param,
101	    ContextPtr context) const
102	{
103	    String name = getAliasToOrName(name_param);
104	    FunctionOverloadResolverPtr res;
105	
106	    auto it = functions.find(name);
107	    if (functions.end() != it)
108	        res = it->second(context);
109	    else
110	    {
111	        name = Poco::toLower(name);
112	        it = case_insensitive_functions.find(name);
113	        if (case_insensitive_functions.end() != it)
114	            res = it->second(context);
115	    }
116	
117	    if (!res)
118	        return nullptr;
119	
120	    if (CurrentThread::isInitialized())
121	    {
122	        auto query_context = CurrentThread::get().getQueryContext();
123	        if (query_context && query_context->getSettingsRef().log_queries)
124	            query_context->addQueryFactoriesInfo(Context::QueryLogFactories::Function, name);
125	    }
126	
127	    return res;
128	}
